INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Adventure Camp (Summer Camp)', 'Nashua Adult Learning Center', 'https://nashuaalc.org/for-children/adventure-camp/', NULL, 'ccharron@nashuaalc.org', '(603) 882-9080 x2220', '40 Arlington St.', 'Nashua', 'NH', '03060', 'New Hampshire', 'day', ARRAY['sports','arts','STEM']::text[], NULL, ARRAY['Swimming','Field trips','Trips to NH State parks','Special theme days','Bicycling','Roller blading','Community service projects','Arts and crafts','Cooperative sports','STEM enrichment']::text[], NULL, 5, NULL, 1, 7, 'A state-licensed full-day summer camp in Nashua for children entering grades 1 through 7. Activities include swimming, field trips, trips to NH state parks, sports, arts and crafts, and STEM. The Learning Center also runs vacation camps during the February and April school breaks.', NULL, NULL, NULL, NULL, 295, 'week', NULL, NULL, NULL, NULL, NULL, NULL, 'Campers walk to Crown Hill Pool on Mondays and Wednesdays, where trained lifeguards are on duty along with camp staff. Children must pass a swim test (swim the length of the pool and tread water for one minute) to go past belly-button depth; retests are each Monday. Lake days at Pawtuckaway State Park are lifeguarded by the State Park.', NULL, NULL, 2026, '24a41fb2-6ecd-5da3-a5b1-c7f4c6856dbb', 'adventure-camp-summer-camp-nashua', ST_GeogFromText('SRID=4326;POINT(-71.4676 42.7654)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=40+Arlington+St.&city=Nashua&state=NH&benchmark=Public_AR_Current&format=json','https://nashuaalc.org/for-children/adventure-camp/','https://nashuaalc.org/wp-content/uploads/2026/06/2026-camp-at-a-glance.pdf','https://nashuaalc.org/wp-content/uploads/2026/06/Parent-Handbook-revised-2026.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Ascend at Camp Monadnock', 'Berea - Camp Monadnock', 'https://www.monadnock.camp/summercamp/', 'https://monadnock.campbrainregistration.com/', 'campmonadnock@berea.org', '603-744-6344', '257 Dublin Road', 'Jaffrey', 'NH', '03452', 'New Hampshire', 'sleepaway', ARRAY['faith','nature','sports']::text[], NULL, ARRAY['Swimming','Archery','Climbing Tower','Ropes Course','Game Room & Lawn Games','Sports','Arts & Crafts','Mini Golf','Paintball','Chapel','Wagon rides','Campfire']::text[], NULL, NULL, NULL, 2, 12, 'A Christian overnight summer camp week in Jaffrey, NH. There are separate weeks for kids (finishing grades 2-5) and teens (finishing grades 6-12). Campers stay in dorms from Sunday to Thursday and do outdoor activities, worship, Bible teaching and small groups.', NULL, NULL, 635, 685, NULL, 'session', NULL, NULL, TRUE, TRUE, NULL, 'You can share allergies and dietary restrictions during registration, and the camp says it works hard to accommodate them. Nurses are on site.', 'Afternoon free time includes swimming and time at the beach by the pond. The page does not describe lifeguarding or swim tests.', NULL, NULL, 2027, 'cf120e45-56ab-500f-b4fc-d0d7c4cf1259', 'ascend-at-camp-monadnock-jaffrey', ST_GeogFromText('SRID=4326;POINT(-72.0599 42.8293)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.monadnock.camp/summercamp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('BCH Camp (Barbara C. Harris Camp)', 'Barbara C. Harris Camp & Conference Center (Episcopal Diocese of Massachusetts)', 'https://bchcenter.org/summer-camp/', 'http://bchcamp.campbrainregistration.com/', 'info@bchcenter.org', '(603) 547-3400', '108 Wally Stone Lane', 'Greenfield', 'NH', '03047', 'New Hampshire', 'sleepaway', ARRAY['faith','nature']::text[], NULL, ARRAY['boating','swimming in the lake','archery','basketball','arts and crafts','challenge course','games in the gym','chapel and evening worship','Rock Out Sesh talent show and dance party']::text[], NULL, NULL, NULL, 0, 12, 'Episcopal overnight camp on Otter Lake in Greenfield, NH, with a Mini Camp for kids who have completed K to 3rd grade, three youth weeks and a High School Camp for 9th to 12th graders. Campers boat, swim in the lake, do archery, basketball, arts and crafts and the challenge course, with chapel and worship each day.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, 'Every registration needs a $250 deposit that is not refunded. Cancel 30 or more days ahead and all other fees are refunded or moved to another week; cancel within 30 days and nothing is refunded, except for illness or a family emergency requested in writing.', 'The page has an inclusion statement saying people of all abilities are welcome. It does not describe any specific accommodations.', 'Campers swim in Otter Lake and go boating from the camp waterfront. The camp''s pages don''t describe swim tests or lifeguarding.', NULL, NULL, 2027, 'b89a28a4-496a-5266-8b2e-801bab2f84f4', 'bch-camp-barbara-c-harris-camp-greenfield', ST_GeogFromText('SRID=4326;POINT(-71.8794 42.9387)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://bchcenter.org/','https://bchcenter.org/summer-camp/','https://bchcenter.org/wp-content/uploads/2026/09/26OCParentGuide-1.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Boys & Girls Club of Greater Salem Summer Camp', 'Boys & Girls Club of Greater Salem', 'https://www.salembgc.org/summercamp', 'https://www.salembgc.org/registration', 'info@salembgc.org', '(603) 898-7709', '3 Geremonty Drive', 'Salem', 'NH', '03079', 'New Hampshire', 'day', ARRAY['sports']::text[], NULL, ARRAY['Swimming (pool)','Outdoor court games','Weekly field trips']::text[], NULL, NULL, NULL, 0, NULL, 'Day camp at the Boys & Girls Club in Salem, NH, for kids from kindergarten up, grouped by the grade they are entering, with a separate teen group. Campers rotate through the Club''s program areas, outdoor courts and pool, and go on a field trip each week.', NULL, NULL, NULL, NULL, 275, 'week', TRUE, NULL, FALSE, NULL, NULL, NULL, 'Campers use the Club''s pool. Send a swimsuit and towel every day.', NULL, NULL, 2026, 'ab784b88-674f-5ff9-8e52-92072e07ba5e', 'boys-and-girls-club-of-greater-salem-summer-camp-salem', ST_GeogFromText('SRID=4326;POINT(-71.2217 42.7883)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://irp.cdn-website.com/f6502fd9/files/uploaded/Copy+of+Fieldtrip+Times+and+Destinations+2026.pdf','https://www.salembgc.org/summercamp']::text[], '2026-11-13', '2026-11-13', TRUE),
('C.A.K.E. Summer Camp (Creative Arts at Keene)', 'MoCo Arts', 'https://www.moco.org/camps/cake/', NULL, 'info@moco.org', '(603) 357-2100', '40 Roxbury St.', 'Keene', 'NH', '03431', 'New Hampshire', 'day', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['dance','theatre','visual art','creative writing','music','tech theatre','film','podcasting','chainmail jewelry design','cooking','tabletop games (Dungeons and Dragons)','musicals','one-act plays','art exhibits']::text[], NULL, NULL, NULL, 3, 12, 'A four-week multi-arts day camp in July for students in grades 3–12. Campers choose their own full-day or half-day schedule of performing and visual arts classes, and the camp ends with a Festival Week of performances and exhibits.', NULL, NULL, 135, 990, 255, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'f20a3c76-84a8-576d-af35-ed160badbf0c', 'c-a-k-e-summer-camp-creative-arts-at-keene-keene', ST_GeogFromText('SRID=4326;POINT(-72.3069 42.9538)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.moco.org/camps/cake/','https://www.moco.org/wp-content/uploads/2026/05/C.A.K.E.-Class-Schedule-2026-UPDATED-V.2.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Deerwood', NULL, 'https://campdeerwood.com/', NULL, 'info@campdeerwood.com', '(603) 279-4237', NULL, 'Holderness', 'NH', '03245', 'New Hampshire', 'sleepaway', ARRAY['sports','nature']::text[], NULL, ARRAY['blacksmithing','waterskiing','rock-climbing','kayaking','mountain-biking','windsurfing','trips']::text[], 'boys', 8, 15, NULL, NULL, 'Deerwood is an overnight camp for boys aged 8-15 on Squam Lake in Holderness, New Hampshire. Along with traditional camp activities, campers can try blacksmithing, waterskiing, rock climbing, kayaking, mountain biking and windsurfing.', NULL, NULL, 7100, 12100, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, 'Camp is on Squam Lake; waterfront activities include waterskiing, kayaking and windsurfing.', NULL, NULL, 2027, 'fbb1b142-beea-54ff-b0e0-36387bd28255', 'camp-deerwood-holderness', ST_GeogFromText('SRID=4326;POINT(-71.5825 43.7618)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://campdeerwood.com/current-schedule/','https://campdeerwood.com/faqs/','https://campdeerwood.com/quick-facts/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Hadar', NULL, 'https://www.camphadar.org/', 'https://hadar.campintouch.com/ui/forms/application/camper/App', 'info@camphadar.org', '(603) 898-6883', '92 Hooker Farm Road', 'Salem', 'NH', '03079', 'New Hampshire', 'day', ARRAY['general','swimming','sports','arts']::text[], NULL, ARRAY['Red Cross swim lessons','free swim','canoeing','kayaking','paddleboats','waterbikes','paddle boards','softball','archery','basketball','tennis','street hockey','beach volleyball','soccer','gaga','music','crafts','dance','drama','Jewish songs and Israeli dance','electives (chugim)']::text[], 'coed', 5, 15, 0, 10, 'Co-ed day camp for ages 5-15 (entering kindergarten through 10th grade CITs) on 17 acres of woods and sandy beach on Captain''s Pond in Salem, NH. Weekly sessions run 9:00 am to 4:00 pm, with Red Cross swim lessons, boating, sports and arts, and optional busing from Chelmsford, Andover and Peabody, MA for $50 a week.', NULL, 'Jewish', 419, 419, 419, 'week', FALSE, TRUE, FALSE, TRUE, 'A $100 deposit per week, per child, is due with the application. After May 1, 2026 the camp keeps the deposit; from June 1, 2026 there are no refunds or credits. Balances were due in full by May 30, 2026.', NULL, 'Sandy beach on Captain''s Pond. The camp runs a Red Cross swim instruction program plus free swim, and boating in canoes, kayaks, paddleboats, waterbikes and paddle boards.', NULL, NULL, 2026, '8d4c5cea-4892-560e-ac67-0b06186fc752', 'camp-hadar-salem', ST_GeogFromText('SRID=4326;POINT(-71.2217 42.7883)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.camphadar.org/','https://www.camphadar.org/current-families/information-for-parents/','https://www.camphadar.org/current-families/transportation-information/','https://www.camphadar.org/programs/daily-programming/','https://www.camphadar.org/programs/dates/','https://www.camphadar.org/programs/registration-information-and-fees/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Hale', 'United South End Settlements (USES)', 'https://www.uses.org/programs/camphale/', 'https://camphale.campmanagement.com/p/campers/login_m.php', 'rpoulin@uses.org', NULL, '92 Millbridge Rd.', 'Sandwich', 'NH', '03227', 'New Hampshire', 'sleepaway', ARRAY['nature','sports','arts']::text[], NULL, ARRAY['swimming','canoeing','kayaking','paddle boarding','arts & crafts','nature education','archery','biking','soccer','basketball','tennis','football','wrestling','gardening','hiking','camping']::text[], NULL, 5, 17, NULL, NULL, 'Overnight camp on Squam Lake in Sandwich, NH, run by Boston''s United South End Settlements for Boston youth ages 5-17. It offers 2-week boys and girls sessions, a 7-day all-gender session, 4-week leadership programs for teens and a 4-day Family Camp, with bus pickup in Boston and fees on a sliding scale by household income.', NULL, NULL, 100.82, 2625, NULL, 'session', NULL, TRUE, TRUE, TRUE, 'All payments are final and non-refundable. Payment plans are available if you contact the camp.', NULL, 'On Squam Lake. The camp aims for 2–4 swim sessions a day and to teach every child to swim and be water-safe. Canoeing, kayaking and paddle boarding are also offered.', NULL, NULL, 2026, 'c4672193-778d-57d3-aa37-bf96b4f327d8', 'camp-hale-sandwich', ST_GeogFromText('SRID=4326;POINT(-71.4431 43.8386)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.uses.org/programs/camphale/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Hawkeye', NULL, 'https://www.camphawkeye.com', 'https://hawkeye.campintouch.com/ui/forms/application/camper/App', 'Jess@camphawkeye.com', '781-315-1297', '165 Camp Good News Rd.', 'Charlestown', 'NH', '03603', 'New Hampshire', 'sleepaway', ARRAY['outdoor','sports','arts']::text[], NULL, ARRAY['archery','adventure course','swimming','climbing tower','zip line','arts & crafts','bugs & dirt (nature)','gaga','multimedia','athletics','ceramics','drama','outdoor skills','Iron Chef (cooking)','weekly hiking or boating trip','cabin sleep outs']::text[], 'coed', 7, 17, NULL, NULL, 'Small, gender-inclusive overnight camp for ages 7-17 in Charlestown, NH, with sessions of 2, 4, 6 or 8 weeks. Tuition covers everything: program materials, out-of-camp hikes and trips, overnights, laundry, food and housing.', NULL, NULL, 3000, 11400, NULL, NULL, NULL, TRUE, TRUE, TRUE, 'You must cancel in writing to Jess@camphawkeye.com. Before January 1, all tuition is refunded, including the deposit. After January 1, the deposit is not refunded. After April 1, half of the tuition is not refunded. After June 1, none of the tuition is refunded.', NULL, 'A 2,600 square foot pool and the stream-fed Lily Pond, with a rope swing. Daily recreational and instructional swim periods; certified lifeguards oversee all waterfront activities.', NULL, NULL, 2027, 'ff2b3ffb-c04b-5b1d-bfae-52200d61f238', 'camp-hawkeye-charlestown', ST_GeogFromText('SRID=4326;POINT(-72.3839 43.2466)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.camphawkeye.com','https://www.camphawkeye.com/activities','https://www.camphawkeye.com/datesandrates','https://www.camphawkeye.com/familyfaq']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp K - Summer Day Camp', 'City of Lebanon Recreation, Arts, and Parks', 'https://lebanonnh.gov/255/Camp-K---Summer-Day-Camp', 'https://secure.rec1.com/NH/city-of-lebanon/catalog', 'Recreation@LebanonNH.gov', '603-448-5121', 'Lebanon Middle School, 3 Moulton Avenue', 'Lebanon', 'NH', '03766', 'New Hampshire', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['Swim lessons','Contracted performances','Arts and crafts','Sports and games','Quiet activity time','Optional day trips (Camp K Hits the Road)']::text[], NULL, 5, 11, NULL, NULL, 'City-run summer day camp for children ages 5-11, held Monday-Friday 7:30 AM-5:00 PM at Lebanon Middle School. Campers are grouped by age (5-6, 7-8, 9-11) and do swim lessons, arts and crafts, sports and games, and performances. An optional trip week, Camp K Hits the Road, follows for ages 7-12.', NULL, NULL, 185, 225, 185, 'week', NULL, NULL, NULL, TRUE, 'A $20 deposit per week is non-refundable. The page gives no other refund terms.', 'Parents must disclose any physical, mental, emotional, social, developmental, or psychological conditions, plus medications and allergies, by June 8. The page does not describe any specific accommodations.', 'Swim lessons at the Lebanon Veterans Outdoor Memorial Pool. Parents must give the camper''s swim level.', NULL, NULL, 2026, '210613bf-78c2-5265-a501-209225176c4f', 'camp-k-summer-day-camp-lebanon', ST_GeogFromText('SRID=4326;POINT(-72.2538 43.6354)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=Lebanon+Middle+School%2C+3+Moulton+Avenue&city=Lebanon&state=NH&benchmark=Public_AR_Current&format=json','https://lebanonnh.gov/255/Camp-K---Summer-Day-Camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Lawrence', 'Merrimack Valley YMCA', 'https://camp.mvymca.org/camp/camp-lawrence/', 'https://mvymca.campbrainregistration.com/', 'camplawrence@mvymca.org', '603-279-6488', '187 Bear Island', 'Laconia', 'NH', '03246', 'New Hampshire', 'sleepaway', ARRAY['sports','nature','arts','performing_arts']::text[], NULL, ARRAY['Archery','Arts & Crafts','Basketball','Campcraft','Canoeing','Fishing','Fitness','Floor Hockey','Frisbee','Improv/Theater','Kayaking','Lacrosse','Music','Outdoor Education','Paddle Boarding','Photography','Ping Pong/Table Tennis','Radio/Broadcasting','Riflery','Ropes Course','Rugby','Sailing','Snorkeling','Soccer','Swimming','Video','Volleyball','Waterskiing','Tennis']::text[], 'boys', 8, 16, NULL, NULL, 'Overnight YMCA camp for boys ages 8-16 on Bear Island in Lake Winnipesaukee, NH, with two-week sessions (one-week sessions only for first-time junior campers). Boys choose their own schedule from sports, waterfront, arts and outdoor-skills activities.', NULL, NULL, 1600, 2675, NULL, NULL, NULL, TRUE, TRUE, TRUE, 'Deposit ($300 per two-week session, $200 per one-week session) is due at registration and is non-refundable. Full balance is due April 1, 2027, with a $150 late fee after that. After April 1, tuition is non-refundable and non-transferable, except for a documented camper illness or death of an immediate family member. Cancellations must be emailed to campinfo@mvymca.org.', 'The camp can handle most dietary preferences (vegetarian, gluten-free, etc.), and staff are told about known food allergies. There are two full-time nurses. Parents of first-time campers fill out a ''Let''s Get Acquainted'' form that the director reviews.', 'Lakefront camp on Lake Winnipesaukee with two natural beaches. Every camper takes swim lessons, and there is open swim. Many staff are certified lifeguards. Waterfront activities include canoeing, kayaking, sailing, paddle boarding, snorkeling, waterskiing and fishing.', NULL, NULL, 2027, 'f3f3cbc9-6c93-5936-aa43-efe7363d80d6', 'camp-lawrence-laconia', ST_GeogFromText('SRID=4326;POINT(-71.4823 43.5765)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://camp.mvymca.org/camp/camp-lawrence/','https://camp.mvymca.org/prepare-for-camp/overnight-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Merriwood', NULL, 'https://www.merriwood.com/', 'https://merriwood.campintouch.com/ui/forms/application/camper/App', 'info@merriwood.com', '(603) 353-9882', '11 Camp Road', 'Orford', 'NH', '03777', 'New Hampshire', 'sleepaway', ARRAY['sports','arts','general']::text[], NULL, ARRAY['tennis','soccer','volleyball','basketball','softball','archery','golf','field hockey','lacrosse','gymnastics','rock wall and zip line','swimming (Red Cross levels)','boating','canoeing','sailing','crew','waterskiing, tubing, kneeboarding and wakeboarding','horseback riding (extra fee)','arts and crafts','dance','drama','trips']::text[], 'girls', NULL, 15, NULL, NULL, 'Traditional overnight camp for girls ages 8-15 on Upper Baker Pond in Orford, NH, founded in 1949. It offers a 7-week full session, 4-week and 3-week half sessions, and 2-week "Splash of Magic" sessions for new campers in current grades 1-4, with land sports, tennis, waterskiing, gymnastics, riding and the arts.', NULL, NULL, 5525, 14600, NULL, 'session', NULL, TRUE, NULL, NULL, NULL, NULL, 'On Upper Baker Pond. All girls take daily swim classes in American Red Cross levels taught by Water Safety Instructors; swimming only at set times in designated areas with lifeguards and a buddy system. Boating, canoeing, sailing, crew and waterskiing are offered.', NULL, NULL, 2027, '0c16f235-f59b-5370-aea6-9f19f29c890d', 'camp-merriwood-orford', ST_GeogFromText('SRID=4326;POINT(-72.0338 43.8833)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.merriwood.com/','https://www.merriwood.com/activities','https://www.merriwood.com/contact-us','https://www.merriwood.com/dates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Moosilauke', NULL, 'https://moosilauke.com/', 'https://moosilauke.campintouch.com/ui/forms/application/camper/App', 'cmoosilauke@gmail.com', '1-800-353-4546', '55 Moosilauke Way', 'Orford', 'NH', '03777', 'New Hampshire', 'sleepaway', ARRAY['sports','nature']::text[], NULL, ARRAY['baseball','basketball','lacrosse','soccer','tennis','archery','ultimate frisbee','flag football','canoeing','kayaking','sailing','swimming','waterskiing/wakeboarding/wake surfing','rowing','stand-up paddle boarding','fishing','Backcountry Leadership Program','hiking','whitewater canoeing and kayaking','rock climbing','mountain biking','woodworking','arts and crafts']::text[], 'boys', 7, 15, NULL, NULL, 'A traditional overnight camp for boys ages 7-15 on a New Hampshire lake, founded in 1904. Campers do land sports, waterfront and outdoor adventure activities, with set periods in the morning and activities they pick each afternoon.', NULL, NULL, 5200, 10200, NULL, 'session', NULL, NULL, NULL, TRUE, 'A $1,000 registration deposit is due at enrollment and becomes non-refundable after December 1, 2026. The page gives no other refund terms.', NULL, 'The camp has a private waterfront and swimming area and about a mile of shoreline. Water activities include swimming, canoeing, kayaking, sailing, waterskiing/wakeboarding/wake surfing, rowing, stand-up paddle boarding and fishing.', NULL, NULL, 2027, '149d0502-a309-5a7d-b98a-896060fbb505', 'camp-moosilauke-orford', ST_GeogFromText('SRID=4326;POINT(-72.0338 43.8833)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://moosilauke.com/about-us/moose-at-a-glance/','https://moosilauke.com/about-us/sessions-dates-tuition/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Mowglis', NULL, 'https://www.mowglis.org', 'https://mowglis.campintouch.com/ui/forms/application/camper/App', NULL, '603-744-8095', '4 Mowglis Drive', 'Hebron', 'NH', '03241', 'New Hampshire', 'sleepaway', ARRAY['nature','sports','arts']::text[], NULL, ARRAY['swimming','hiking','rock climbing','crew','archery','nature studies','woodworking','cooking','arts and crafts','hiking trips','evening campfires']::text[], 'boys', 7, 15, NULL, NULL, 'Overnight summer camp for boys on Newfound Lake in Hebron, NH, with traditional outdoor activities such as swimming, hiking, climbing, crew and archery. About 100 campers, one counselor for every three campers, and campers sleep in screened open-air dormitories grouped by age.', NULL, NULL, 6370, 11300, NULL, 'session', NULL, NULL, NULL, TRUE, 'A $500 registration deposit, applied to tuition, is due at enrollment and is non-refundable. Tuition payments are non-refundable after January 31; 50% is due March 15 and the rest by May 15. The camp recommends tuition insurance.', NULL, 'Camp is beside Newfound Lake. Swimming and crew are listed as activities. The page gives no details on swim instruction or waterfront supervision.', NULL, NULL, 2027, '63664b35-4bce-56f7-a4f0-aded4120986c', 'camp-mowglis-hebron', ST_GeogFromText('SRID=4326;POINT(-71.792 43.6936)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.mowglis.org/best-boys-summer-camp-in-new-hampshire/','https://www.mowglis.org/future-families/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Naticook', 'Merrimack Parks & Recreation Department', 'https://merrimackparksandrec.org/camp-naticook', 'https://merrimack.recdesk.com/Community/Program?category=48', NULL, '603-420-1662', '116 Naticook Road', 'Merrimack', 'NH', '03054', 'New Hampshire', 'day', ARRAY['sports','arts','nature','performing_arts']::text[], NULL, ARRAY['sports & games','arts & crafts','nature exploration & hiking','swimming','American Red Cross swim lessons','canoeing/boating','archery','theater/drama','Friday special events']::text[], NULL, NULL, NULL, 0, 5, 'A town-run traditional day camp at Wasserman Park on Naticook Lake in Merrimack, NH, for children entering Kindergarten through 5th grade. Campers do sports, games, arts and crafts, nature activities, swimming, boating, archery and theater, and a daily hot lunch is included.', NULL, NULL, 325, 375, 325, 'week', TRUE, NULL, TRUE, TRUE, 'Each session requires a $50 non-refundable deposit, and the full balance is due 45 days before the session starts. If you cancel at least 30 days ahead, you lose only the deposit. Cancelling 15–30 days ahead gets a 50% refund of what you paid, minus the deposit, and there are no refunds within 15 days of the start. Transfers to another session have no penalty if made at least 30 days ahead. Medical cancellations within 14 days of the start need a doctor''s letter and get a 50% refund of the remaining amount, minus the deposit.', 'The camp no longer provides one-to-one aides. Campers must be able to take part in their assigned group and tell staff what they need. Families are encouraged to call the camp to discuss fit. For one-to-one support, the camp suggests Camp Allen (Bedford), Recreational Education Center (Londonderry) or Camp Starfish (Rindge).', 'The camp is on Naticook Lake. Campers go on canoe trips and have free swim time at the waterfront and beach. American Red Cross swim lessons are offered at no extra cost (the page''s text says ''Returning for 2025'').', NULL, NULL, 2026, '387b219c-0a8b-5f9e-99f4-88cc902009be', 'camp-naticook-merrimack', ST_GeogFromText('SRID=4326;POINT(-71.5199 42.852)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://merrimackparksandrec.org/camp-naticook']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Nokomis', 'Merrimack Valley YMCA', 'https://camp.mvymca.org/camp/camp-nokomis/', 'https://mvymca.campbrainregistration.com/', 'campnokomis@mvymca.org', '603-279-4918', '80 Bear Island', 'Laconia', 'NH', '03246', 'New Hampshire', 'sleepaway', ARRAY['sports','arts','nature','performing_arts']::text[], NULL, ARRAY['Archery','Basketball','Campcraft','Canoeing','Ceramics','Copper Enameling','Dance','Dramatics','General Crafts','Improv/Theater','Kayaking','Leathercraft','Nature','Photography','Ropes','Rowing','Sailing','Silvercraft','Soccer','Swimming','Tennis','Volleyball','Waterskiing','Windsurfing','Woodworking']::text[], 'girls', 8, 16, NULL, NULL, 'Overnight YMCA camp for girls ages 8-16 on Bear Island in Lake Winnipesaukee, NH, with two-week sessions. Campers choose from sports, waterfront and craft activities and live in cabins of 8-12 campers with two staff.', NULL, NULL, 2675, 2675, NULL, NULL, NULL, TRUE, TRUE, TRUE, 'A $300 deposit per two-week session is due at registration. It is non-refundable and can''t be moved to another session, season or sibling. The full balance is due by April 1, 2027, with a $150 late fee after that date. After April 1, 2027, tuition is non-refundable and non-transferable. Refunds are only given for a documented illness of the camper or the death of an immediate family member. Cancellations must be emailed to campinfo@mvymca.org.', 'The camp can accommodate most dietary preferences (vegetarian, gluten-free, etc.), and staff are told about identified food allergies. No information on support for disabilities or other special needs.', 'Island camp on Lake Winnipesaukee with two beaches. Swim instruction for all levels, plus canoeing, kayaking, rowing, sailing, waterskiing and windsurfing. Many staff are certified lifeguards.', NULL, NULL, 2027, 'bd550c70-8771-59ec-bf5e-40d2ab9659b0', 'camp-nokomis-laconia', ST_GeogFromText('SRID=4326;POINT(-71.4823 43.5765)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://camp.mvymca.org/camp/camp-nokomis/','https://camp.mvymca.org/prepare-for-camp/overnight-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Onaway', 'Camp Onaway', 'https://www.camponaway.org/', 'https://www.camponaway.org/enroll-here', 'bbeckman@camponaway.org', '610-525-0676', '27 Camp Onaway Drive', 'Hebron', 'NH', '03241', 'New Hampshire', 'sleepaway', NULL, NULL, ARRAY['Swimming','Boating','Canoeing','Crew','Sailing','Tennis','Woodworking','Dance','Theatre','Music','Arts','Nature / Hiking','Wilderness trips','Leadership programs']::text[], 'girls', 9, 15, 4, 11, 'A traditional residential summer camp for girls ages 9 to 15 on Newfound Lake in Hebron, NH, since 1911. The main program is a 7-week session for rising 5th to 10th graders, with 3-week Wendies sessions for rising 4th graders.', NULL, NULL, 7600, 12200, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, 'Camp is on Newfound Lake. Every camper has daily swimming instruction; campers progress through boating, then canoeing, and add crew in their final two years. Sailing is scheduled for all campers.', NULL, NULL, 2027, 'caa944cc-1884-5bd4-840d-686bed1c581d', 'camp-onaway-hebron', ST_GeogFromText('SRID=4326;POINT(-71.792 43.6936)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.camponaway.org/','https://www.camponaway.org/activities','https://www.camponaway.org/enroll-here']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Otter', 'Merrimack Valley YMCA', 'https://camp.mvymca.org/camp/camp-otter/', 'https://mvymca.campbrainregistration.com/', 'campotter@mvymca.org', '603-893-4911', '66 Hooker Farm Road', 'Salem', 'NH', '03079', 'New Hampshire', 'day', ARRAY['sports','nature','arts']::text[], NULL, ARRAY['Swimming','Boating (rowing, canoeing, paddleboarding, kayaking)','Archery','Air rifle','High and low ropes course','Zip line','Arts & crafts','Fishing','Gaga','Basketball','Volleyball','Hockey','Softball/baseball','Kickball','Soccer','Flag football','Game center (ping pong, carpet ball)','Weekly themes']::text[], 'coed', 6, 13, NULL, NULL, 'YMCA day camp for ages 6-13 on Captain''s Pond in Salem, NH, with weekly themes, daily swimming, boating, archery, ropes courses, sports and arts & crafts. Bus transportation from Merrimack Valley and Southern NH towns is included in the weekly rate.', NULL, NULL, 405, 405, 405, 'week', NULL, TRUE, FALSE, TRUE, '$50 per-week deposit is non-refundable and non-transferable. Full balance due by June 1; after June 1 balances are non-refundable and non-transferable. Refunds only for a documented camper illness or death of an immediate family member; none for absences or bad weather. Cancellations must be emailed to campinfo@mvymca.org.', 'The page does not describe a formal special needs program. Families with a specific need or circumstance are asked to email campotter@mvymca.org. A featured story describes a camper with leukemia who attended with planning by the director, nursing and counseling staff, including rest in a quiet space.', 'Camp is on Captain''s Pond. Instructional and/or free swim every day; lessons follow YMCA of USA guidelines. Boating taught by lifeguards and small-craft-certified instructors; campers must pass a swim test to use kayaks.', NULL, NULL, 2027, '3db6fe6e-43e4-5fdd-b99a-918d77d9fcb6', 'camp-otter-salem', ST_GeogFromText('SRID=4326;POINT(-71.2217 42.7883)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://camp.mvymca.org/camp/camp-otter/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Pasquaney', 'Camp Pasquaney', 'https://pasquaney.org/', 'https://pasquaney.org/future-families/how-to-enroll', 'office@pasquaney.org', '603-744-8043', '19 Pasquaney Lane', 'Hebron', 'NH', '03241', 'New Hampshire', 'sleepaway', ARRAY['nature','sports','performing_arts']::text[], NULL, ARRAY['Baseball','Canoeing','Crew','Diving','Nature','Sailing','Woodshop','Swimming','Tennis','Water sports','Camping expeditions','Hiking','Theater']::text[], 'boys', 11, 16, NULL, NULL, 'A seven-week overnight summer camp for boys ages 11 to 16 on Newfound Lake in Hebron, NH, founded in 1895. The 2027 season runs June 26 to August 15 and includes camping expeditions, a long hike, a theater play, crew races and a water sports weekend.', NULL, NULL, 11725, 11725, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, 'Camp is on a half mile of Newfound Lake shoreline. Each boy takes a series of swim tests; counsellors teach swimmers of all levels, and the diving raft has a springboard and a high dive.', NULL, NULL, 2027, '25706589-5570-5803-9946-5e7bfe4cbe25', 'camp-pasquaney-hebron', ST_GeogFromText('SRID=4326;POINT(-71.792 43.6936)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://pasquaney.org/','https://pasquaney.org/camp-life/activities','https://pasquaney.org/future-families/dates-rates','https://pasquaney.org/future-families/how-to-enroll']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Robin Hood', NULL, 'https://www.camprobinhood.com/', 'https://robinhood.campintouch.com/ui/forms/application/camper/App', 'info@camprobinhood.com', '603-539-4500', '65 Robin Hood Lane', 'Freedom', 'NH', '03836', 'New Hampshire', 'sleepaway', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Team sports','Individual sports','Waterfront','Hiking & trips','Fitness','The arts','Private instruction','Horseback riding','Tennis','Inter-camp competition']::text[], 'coed', 6, 16, NULL, NULL, 'Overnight brother/sister summer camp on Lake Ossipee in Freedom, NH, for boys and girls ages 6 to 16, with separate Boys Camp and Girls Camp that share meals and assemblies. Summer 2027 offers a four-week First Session and a seven-week Full Session.', NULL, NULL, 11675, 17000, NULL, 'session', NULL, TRUE, TRUE, NULL, 'Tuition is refundable minus a $500 processing fee until January 1, 2027. After that date tuition is non-refundable.', NULL, 'Nearly a mile of waterfront on the Broad Bay section of Lake Ossipee. Certified instructors teach swimming at all levels, followed by free swim; also sailing, canoeing, kayaking, paddle boarding, waterskiing, wakeboarding, tubing, fishing and an inflatable water park. Older campers can take a lifeguarding course.', NULL, NULL, 2027, 'b0842e8f-d244-50ff-aaa2-6b76a8f83c1f', 'camp-robin-hood-freedom', ST_GeogFromText('SRID=4326;POINT(-71.0752 43.842)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.camprobinhood.com/about-camp-robin-hood/activities-waterfront.php','https://www.camprobinhood.com/about-camp-robin-hood/boys-girls-camp-experience.php','https://www.camprobinhood.com/about-camp-robin-hood/dates-fees-faqs.php','https://www.camprobinhood.com/about-camp-robin-hood/new-hampshire-camp-activities.php']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Robindel', NULL, 'https://robindel.com/', 'https://robindel.campintouch.com/ui/forms/application/camper/App', 'jolly@robindel.com', '215-518-6021', '81 Geneva Point Road', 'Moultonborough', 'NH', '03254', 'New Hampshire', 'sleepaway', ARRAY['sports','nature']::text[], NULL, ARRAY['Archery','Arts & crafts','Culinary','Basketball','Fitness','Gymnastics','Horseback riding (optional, extra fee)','Lacrosse','Mountain biking','Performing arts','Photography','Pickleball','Ropes','Ski','Soccer','Softball','Swim','Outdoor adventure','Tennis','Water crafts','Volleyball','Senior trips: Maine coast camping, white water rafting, rock climbing, Canada trip']::text[], 'girls', NULL, NULL, 1, 10, 'An all-girls overnight summer camp on Lake Winnipesaukee in Moultonboro, NH, running since 1951, for girls entering 1st through 10th grade. The main program is the seven-week CR Full Experience, with a two-week introductory session, 2 Weeks on Winni, for girls entering 2nd grade.', NULL, NULL, 5500, 17300, NULL, 'session', NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, 'caf12e52-57ba-5c63-8294-654d0e9cd76e', 'camp-robindel', ST_GeogFromText('SRID=4326;POINT(-71.3686 43.7205)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://robindel.com/contact-us','https://robindel.com/dates-rates','https://robindel.com/girls-camp/activities','https://robindel.com/girls-camp/our-camp-program']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Starfish', 'Camp Starfish', 'https://campstarfish.org', 'https://campstarfish.org/programs/first-time-camper-application/', 'info@campstarfish.org', '603-899-9590', '12 Camp Monomonac Rd.', 'Rindge', 'NH', '03461', 'New Hampshire', 'sleepaway', ARRAY['special_needs']::text[], NULL, ARRAY['Soccer','Kayaking','Raft building','Campfire','Talent show']::text[], NULL, 6, 17, NULL, NULL, 'An overnight camp on Lake Monomonac in Rindge, NH for children ages 6 to 17 with emotional, behavioral and learning challenges. Its core programs (two-week Navigators and OCP sessions, five-day Lite and Havvago) have one staff member for every camper; shorter specialty weeks serve siblings and teens.', NULL, NULL, 1000, 5350, NULL, 'session', NULL, NULL, TRUE, TRUE, NULL, 'Serves children with emotional, behavioral and learning challenges. Core programs keep one staff member for every camper, but no child is assigned a single dedicated adult. A nurse lives on site; there is no doctor on site. Campers should feed themselves, use the toilet on their own, and be able to get around hilly ground. Not suitable for children with feeding tubes, IV medications or daily injections, or with frequent violent behavior. Accessibility is still being improved, so families of campers with mobility limits should call before applying. Vegetarian meals are available; gluten-free is partly available; kosher is not.', 'More than 1/2 mile of shoreline on Lake Monomonac, with access from several private beaches.', NULL, NULL, 2026, '6f3dc84e-886a-582f-9435-fe28f01b8089', 'camp-starfish-rindge', ST_GeogFromText('SRID=4326;POINT(-72.0132 42.7567)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campstarfish.org/programs/1-to-1/','https://campstarfish.org/programs/1-to-1/navigators/','https://campstarfish.org/programs/first-time-camper-application/','https://campstarfish.org/programs/parent-guardian-faq/','https://campstarfish.org/wp-content/uploads/2025/10/2026-Dates-and-Rates.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Tel Noar', 'The Cohen Camps', 'https://www.cohencamps.org/tel-noar/', 'https://telnoar.campintouch.com/ui/forms/application/camper/App', 'info@camptelnoar.org', '603.329.6931', '167 Main Street', 'Hampstead', 'NH', '03841', 'New Hampshire', 'sleepaway', ARRAY['faith','sports','arts','nature']::text[], NULL, ARRAY['Swimming (pool)','Lake paddling','Basketball','Tennis','Arts','Dance','Photography','Campfire singing','Trip days','Electives']::text[], 'coed', NULL, NULL, NULL, NULL, 'A small, co-ed Jewish overnight camp in Hampstead, New Hampshire, founded in 1945. Sessions are 2, 3.5, or 7 weeks long, and campers choose their own activities and electives.', NULL, NULL, 4650, 14490, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, 'The page mentions a pool for swimming and a lake for paddling. It gives no details on swim instruction or lifeguard staffing.', NULL, NULL, 2027, 'bf9aedd4-69d2-5933-893d-7128a43fe839', 'camp-tel-noar-hampstead', ST_GeogFromText('SRID=4326;POINT(-71.1719 42.8811)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.cohencamps.org/tel-noar/','https://www.cohencamps.org/tel-noar/summer/dates-tuition/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Tevya', 'The Cohen Camps', 'https://www.cohencamps.org/tevya/', 'https://tevya.campintouch.com/ui/forms/application/camper/App', 'info@camptevya.org', '603.673.4010', '1 Mason Road', 'Brookline', 'NH', '03033', 'New Hampshire', 'sleepaway', ARRAY['faith','sports','arts','nature']::text[], NULL, ARRAY['Swimming','Paddling','Basketball','Tennis','Arts','Dance','Photography','Jewish life and traditions','Electives']::text[], 'coed', NULL, NULL, NULL, NULL, 'A co-ed Jewish overnight camp on Lake Potanipo in Brookline, New Hampshire, running since 1940. It offers 3.5-week and 7-week sessions, plus short first-timer sessions of 1 and 2 weeks, with Jewish life, waterfront, sports and arts activities.', NULL, NULL, 2325, 14490, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, 'The camp is on Lake Potanipo, and campers swim and paddle there. The page gives no details on swim instruction, testing or lifeguarding.', NULL, NULL, 2027, '5baa1ca7-c664-5e0b-b6bc-c617025ecafb', 'camp-tevya-brookline', ST_GeogFromText('SRID=4326;POINT(-71.6757 42.7493)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.cohencamps.org/tevya/','https://www.cohencamps.org/tevya/summer/dates-tuition/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Wa-Klo', 'Camp Wa-Klo', 'https://www.campwaklo.com/', 'https://campwaklo.campfront.com/', NULL, '603-563-8531', '435 Page Rd.', 'Dublin', 'NH', '03444', 'New Hampshire', 'sleepaway', ARRAY['sports','nature']::text[], NULL, ARRAY['Land sports','Water sports','Creative arts','Equestrian (horseback riding at extra cost)','Trips','Community service','Environmental stewardship','Evening programs']::text[], 'girls', NULL, NULL, 2, 11, 'Overnight summer camp for girls in Dublin, NH, with 2-, 3-, 4- and 7-week stays for rising grades 2-10 and a Leadership Training Group for girls entering grade 11. Horseback riding is available at extra cost.', NULL, NULL, 7250, 14300, NULL, 'session', NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '688d8040-b0e6-50cb-a962-5995c0008afc', 'camp-wa-klo-dublin', ST_GeogFromText('SRID=4326;POINT(-72.0698 42.8893)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.campwaklo.com/','https://www.campwaklo.com/about/activities/','https://www.campwaklo.com/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Walt Whitman', NULL, 'https://www.campwalt.com/', 'https://waltwhitman.campintouch.com/ui/forms/application/camper/App', NULL, '1-800-657-8282', '1000 Cape Moonshine Road', 'Piermont', 'NH', '03779', 'New Hampshire', 'sleepaway', ARRAY['sports','arts','adventure']::text[], NULL, ARRAY['Athletics','Arts','Adventure','Water Sports','Ceramics','Woodworking','Crafts','Drama','Music','Ropes courses','Hiking','Whitewater rafting','Overnight camping trips']::text[], 'coed', NULL, NULL, 2, NULL, 'A coed overnight summer camp in Piermont, New Hampshire, built mainly around a seven-week full summer, with shorter first and second sessions for some age groups. The program mixes athletics, arts, adventure and water sports.', NULL, NULL, 9400, 17600, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '372c77e3-5912-5939-bce6-b29f14ab4217', 'camp-walt-whitman-piermont', ST_GeogFromText('SRID=4326;POINT(-72.0013 43.9619)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.campwalt.com/about/faqs/','https://www.campwalt.com/about/program-activities/','https://www.campwalt.com/about/sessions-enrollment/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Waukeela', NULL, 'https://www.waukeela.com', 'https://waukeela.campbrainregistration.com/', 'gillian@waukeela.com', '(603) 447-2260', NULL, 'Eaton Center', 'NH', '03832', 'New Hampshire', 'sleepaway', ARRAY['sports','arts','outdoor']::text[], NULL, ARRAY['Kayaking','Canoeing','Paddleboarding','Sailing','Swimming','Synchronized swimming','Archery','Field sports','Tennis','Golf','Outdoor living skills','Arts and crafts','Pottery','Textiles','Drama','Dance','Film','Music','Hiking','Outdoor camping','Whitewater canoeing','Horseback riding (extra cost)','Rock climbing (extra cost)','Junior lifeguard training']::text[], 'girls', NULL, NULL, NULL, NULL, 'Overnight summer camp for girls on Crystal Lake near Eaton Center, New Hampshire, running since 1922. It offers two sessions of about 3½ weeks, a 7-week full summer, and 2-week sessions for first-time campers entering grades 3 to 5.', NULL, NULL, 6000, 12500, NULL, NULL, NULL, TRUE, NULL, TRUE, 'You pay a $1,000 registration fee to sign up. It is fully refundable until January 31. Siblings (2nd, 3rd or 4th child) get 10% off the registration fee.', NULL, NULL, NULL, NULL, 2027, '25c37328-14e2-5c05-9906-868df5b20004', 'camp-waukeela-eaton-center', ST_GeogFromText('SRID=4326;POINT(-71.0475 43.907)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.waukeela.com/camp-families-dates-rates','https://www.waukeela.com/experience-activities-trips','https://www.waukeela.com/summer-programs']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Wicosuta', 'Camp Wicosuta', 'https://www.campwicosuta.com/', 'https://www.campwicosuta.com/story/enroll/', 'info@campwicosuta.com', '914-946-0927', '21 Wicosuta Drive', 'Hebron', 'NH', '03241', 'New Hampshire', 'sleepaway', ARRAY['sports','arts','performing_arts','outdoor']::text[], NULL, ARRAY['Athletics & Sports','Culinary Arts','Dance & Fitness','Outdoor Adventures','Theatre','Visual Arts','Water Sports','Off-site trips','Horseback riding (optional, extra cost)','Ice skating (optional, extra cost)','Golf (optional, extra cost)','Private lessons in tennis, soccer and gymnastics (optional, extra cost)']::text[], 'girls', NULL, NULL, 1, 9, 'Overnight summer camp for girls in Hebron, NH, running since 1920, with campers grouped by grade from 1st through 9th grade. It offers two 3½-week sessions and a 2-week Explorers session for younger first-time campers.', NULL, NULL, 7125, 10350, NULL, NULL, NULL, TRUE, NULL, NULL, '$1,500 deposit with enrollment, which includes a $200 non-refundable application fee. $3,000 is due Jan 31, 2027, and the rest is due Apr 1, 2027. Without CAP: everything except the $200 fee is refundable until Jan 31, 2027. After that the cancellation fee is $1,500 (Feb 1–Mar 16), $2,000 (Mar 17–Apr 30), or $3,500 (May 1–31), and nothing is refunded after June 1. With the optional Camper Assurance Program (CAP), you can cancel for any reason before camp starts and get money back as a refund or a credit, depending on the date. CAP must be bought at enrollment, by Mar 16, 2027 at the latest. Cancellations must be in writing.', NULL, NULL, NULL, NULL, 2027, '2c269cb1-5744-5c8d-96ce-465a0ef6b54f', 'camp-wicosuta-hebron', ST_GeogFromText('SRID=4326;POINT(-71.792 43.6936)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.campwicosuta.com/dates-rates/','https://www.campwicosuta.com/progressive-program/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Winaukee', NULL, 'https://winaukee.com', 'https://winaukee.campintouch.com/ui/forms/application/camper/App', 'matt@winaukee.com', '(800) 487-9157', '432 Winaukee Road', 'Moultonborough', 'NH', '03254', 'New Hampshire', 'sleepaway', ARRAY['sports','nature','arts']::text[], NULL, ARRAY['Waterskiing','Wakeboarding','Kneeboarding','Wakesurfing','Sailing','Canoeing','Kayaking','Paddleboarding','Swimming instruction','Recreational swim','Inflatables','Beach volleyball','Fishing','Team sports','Individual sports','Arts & making','Outdoor adventure']::text[], 'boys', 7, 15, NULL, NULL, 'An overnight camp for boys ages 7-15 on Lake Winnipesaukee in Moultonborough, NH, with a strong focus on sports. It has two campuses, the Mainland for boys 7-12 and the Island for boys 13-15. Activities include waterskiing, sailing, paddling, swim lessons and fishing, plus team sports, arts and outdoor adventure.', NULL, NULL, 5500, 16400, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Waterfront on Lake Winnipesaukee. Swimming is supervised by Red Cross Certified Lifeguards and Water Safety Instructors. Mainland boys take part in a Learn to Swim Program, with lessons as often as their swim level requires. Lifeguards with waterski experience drive the ski boats. PFDs are required on motor boats and during all towed watersports. Sailing (Sunfish) and paddleboarding start in shallow water under lifeguard supervision.', NULL, NULL, 2027, '11625670-79df-5db8-b7db-cd5e1f042567', 'camp-winaukee', ST_GeogFromText('SRID=4326;POINT(-71.3686 43.7205)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://winaukee.com/','https://winaukee.com/activities/water-sports','https://winaukee.com/contact-us','https://winaukee.com/dates-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Young Judaea (Camp YJ)', 'Camp Young Judaea', 'https://campyj.org', 'https://campyj.org/register', 'info@campyj.org', '(781) 237-9410', '9 Camp Road', 'Amherst', 'NH', '03031', 'New Hampshire', 'sleepaway', ARRAY['faith','sports','arts']::text[], NULL, ARRAY['Basketball','Soccer','Softball','Flag football','Volleyball','Lacrosse','Tennis','Archery','Swimming','Waterskiing','Canoeing','Kayaking','Fishing','Stand-up paddleboarding','Sailing','Arts and crafts','Ceramics','Woodworking','Drama','Dance','Music','Videography and photography','Low ropes course','Climbing tower','Campcraft and overnight camping','Horseback riding (extra fee)','Jewish life']::text[], NULL, 8, 15, NULL, NULL, 'An independent, non-profit Jewish overnight camp on Baboosic Lake in Amherst, NH, for kids ages 8-15 from a range of Jewish backgrounds. For 2027 it offers a seven-week full season, a four-week first session, a three-week second session, and two-week sessions for first-time campers.', NULL, 'Jewish', 4600, 13900, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'Waterfront on Baboosic Lake plus a pool, both staffed by First Aid, CPR and AED trained Red Cross instructors. Waterfront electives include waterskiing, canoeing, kayaking, fishing, paddleboarding and sailing.', NULL, NULL, 2027, '1c88f024-b33f-5356-ad0a-9d9fad391e14', 'camp-young-judaea-camp-yj-amherst', ST_GeogFromText('SRID=4326;POINT(-71.6005 42.8748)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://campyj.org/','https://campyj.org/2027dates','https://campyj.org/activities','https://campyj.org/scholarships']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Eagle Camp', 'Portsmouth Christian Academy', 'https://pcaschool.org/summer-eagle-camp/', NULL, NULL, '(603) 742-3617', '20 Seaborne Drive', 'Dover', 'NH', '03820', 'New Hampshire', 'day', ARRAY['faith']::text[], NULL, ARRAY['outdoor activities','field trips to local attractions and community partners','crafts','games','weekly themed activities','leadership opportunities','spiritual development']::text[], NULL, 3, NULL, NULL, 7, 'A Christian day camp at Portsmouth Christian Academy in Dover, NH. In 2026 it ran eight weeks, June 15 to August 7, each week with its own theme, games, crafts, outdoor time and field trips to local attractions. Campers are grouped as Eaglets (age 3 through incoming kindergarten) and Eagles (incoming grades 1-7).', NULL, 'Christian', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '11186d90-1e83-54dd-8f2b-85a6064c1295', 'eagle-camp-summer-eagle-camp-dover', ST_GeogFromText('SRID=4326;POINT(-70.8836 43.1864)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://pcaschool.org/summer-eagle-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Fleur de Lis Camp', 'Fleur de Lis Camp', 'https://www.fleurdeliscamp.org', 'https://fleurdelis.campintouch.com/ui/forms/application/camper/App', 'executivedirector@fleurdeliscamp.org', '603-585-7751', '120 Howeville Road', 'Fitzwilliam', 'NH', '03447', 'New Hampshire', 'sleepaway', NULL, NULL, ARRAY['Swimming','Tennis','Ceramics','Crafts','Theater arts','Surfing','Sailing','Knitting','Archery','Waterskiing','Riflery','Canoeing','Field sports','Kayaking','Horseback riding','Dance','Stained glass','Paddleboarding']::text[], 'girls', NULL, NULL, 3, 10, 'A non-profit classic sleepaway camp for girls, founded in 1929, on Laurel Lake in Fitzwilliam, NH. Sessions run from 2 to 7 weeks for rising 3rd–10th graders. Rising 11th and 12th graders can apply to a Counselor in Training program.', NULL, NULL, 3150, 9950, NULL, NULL, NULL, NULL, NULL, TRUE, 'You pay a $500 deposit when you register. If you applied for tuition assistance and can''t enroll after reviewing the aid offer, the deposit is refunded. The page gives no other refund terms.', NULL, 'The camp is on the shores of Laurel Lake. Swimming, sailing, waterskiing, canoeing, kayaking and paddleboarding are among the activities campers choose from. The pages give no details on swim tests or lifeguarding.', NULL, NULL, 2027, '7bbd2d5a-d41e-530c-8c75-886301a60c72', 'fleur-de-lis-camp-fitzwilliam', ST_GeogFromText('SRID=4326;POINT(-72.153 42.7532)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.fleurdeliscamp.org/activities','https://www.fleurdeliscamp.org/dates-and-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Fort Friendship Day Camp', 'Daniel Webster Council d/b/a Scouting America New Hampshire', 'https://fortfriendshipdaycamp.com/', 'https://scoutingevent.com/330-108273', NULL, '(603) 623-5962', '300 Blondin Road', 'Manchester', 'NH', '03109', 'New Hampshire', 'day', ARRAY['nature','sports','arts']::text[], NULL, ARRAY['Swimming and waterfront games','Boating','Archery','BB range','Nature hikes','Team challenges and obstacle play','Arts and crafts','Camp-wide games and themed events']::text[], NULL, 5, 11, 1, 5, 'A weekday day camp for children entering grades 1–5 at Camp Carpenter in Manchester, NH. It is open to Scouts and non-Scouts, and activities include daily swimming and boating on a private lake, archery and BB, nature hikes, and crafts.', NULL, NULL, 330, NULL, NULL, NULL, TRUE, NULL, TRUE, NULL, NULL, NULL, 'Private lake with daily swimming, boating and waterfront games. Staff are trained in waterfront supervision and swim classification.', NULL, NULL, 2026, 'e0d4c5aa-e905-5961-92de-a953c5c1e8b7', 'fort-friendship-day-camp-manchester', ST_GeogFromText('SRID=4326;POINT(-71.4548 42.9956)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://fortfriendshipdaycamp.com/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Greenland Day Camp (YMCA Camp Gundalow)', 'The Granite YMCA (YMCA of the Seacoast)', 'https://www.graniteymca.org/camps/day-camp/greenland-day-camp/', 'https://ymcagranite.sgasoftware.com/Sales/Product?ProductID=62001-68999&ProductTypeID=610,650&DT=GroupedList&DL=100', 'zbrikiatis@graniteymca.org', '603.994.4155', NULL, 'Greenland', 'NH', '03840', 'New Hampshire', 'day', ARRAY['sports','arts','STEM','performing_arts']::text[], NULL, ARRAY['swimming','STEM','creative arts','sports','archery','arts & crafts','team building','field trips (Voyagers)','football','all-star sports','theater','Lego','fort building','DIY art','leadership programs (LIT/CIT)']::text[], NULL, NULL, NULL, 1, 9, 'YMCA day camp at Camp Gundalow in Greenland, NH, for children entering grades 1–9, grouped by grade, with swimming, archery, sports, arts and STEM; there are also specialty camps and a trip-based camp for grades 7–9. The camp also runs teen leadership programs: LIT for grades 8–9 and CIT for grades 10–11.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'Each week needs a $35 nonrefundable deposit. Cancel more than 6 weeks before the camp week: full refund less the deposit. Cancel 3 to 6 weeks before: refund less a $65 admin fee and the deposit. Cancel less than 3 weeks before: no refund. Payment is due in full at registration.', NULL, 'The page lists swimming as a regular activity. It does not say whether this is a pool or open water, or how swim tests are done.', NULL, NULL, 2026, 'e5a908e6-d4c8-5b4c-8021-4b68e5129b2b', 'greenland-day-camp-ymca-camp-gundalow-greenland', ST_GeogFromText('SRID=4326;POINT(-70.8456 43.0397)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://tools.usps.com/zip-code-lookup.htm?citybyzipcode','https://www.graniteymca.org/camps/day-camp/greenland-day-camp/','https://www.graniteymca.org/dev/wp-content/uploads/2024/01/Summer-Billing-Schedule.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Guided Discoveries Summer Camp', 'Squam Lakes Natural Science Center', 'https://nhnature.org/learn/camp/', 'https://nhnature.campbrainregistration.com/', 'info@nhnature.org', '603-968-7194', '23 Science Center Road', 'Holderness', 'NH', '03245', 'New Hampshire', 'day', ARRAY['nature']::text[], NULL, ARRAY['Up-close animal encounters','Live Animal Exhibit Trail walks','Outdoor exploration','Games','Crafts and nature art','Animal care (Junior Animal Keepers)','Ceramics (Nature of Clay)','Nature journaling','Orienteering','Fort building','Conservation projects (Earth Camp)']::text[], NULL, 5, 13, NULL, NULL, 'A nature day camp at Squam Lakes Natural Science Center in Holderness, NH, for ages 5 to 13. Week-long half-day and full-day sessions mix outdoor exploration, games, crafts and up-close meetings with the center''s live animals. The center also runs February and April break camps.', NULL, NULL, 260, 420, NULL, NULL, NULL, NULL, NULL, TRUE, 'A $25 administration fee applies to all cancellations. Cancel more than 30 days before a session: full refund minus $25. Cancel 14–30 days before: 50% refund minus $25. Cancel less than 14 days before: no refund. If enrollment is low, the center cancels week-long programs on the Wednesday before the start date and gives a full refund. Families may also transfer to another session at no extra cost if space allows.', NULL, NULL, NULL, NULL, 2026, 'ac3364e0-3f1d-502c-be6d-e5822ad5a9ab', 'guided-discoveries-summer-camp-holderness', ST_GeogFromText('SRID=4326;POINT(-71.5825 43.7618)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://nhnature.org/learn/camp/','https://nhnature.org/wp-content/uploads/2026/05/2026_20Guided_Discoveries_Schedule_Sessions.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hanover Parks & Recreation Camps', 'Hanover Parks & Recreation', 'https://www.hanovernh.org/716/Camps', 'https://hanovernh.perfectmind.com/SocialSite/MemberRegistration/MemberSignIn', 'parksandrec@hanovernh.org', '603-643-2411', '63 Lyme Road', 'Hanover', 'NH', '03755', 'New Hampshire', 'day', NULL, NULL, ARRAY['Themed indoor and outdoor activities','Time at Storrs Pond','Special events','Field trips','Arts and crafts','Free play','Gym time','Walks to a local park','Library trips','Outdoor games','Water activities','Mink Brook outdoor adventures']::text[], NULL, 2, NULL, NULL, 5, 'Town-run day camps for preschoolers (ages 2-4) and children entering kindergarten through grade 5: 6 themed summer weeks at Richmond Middle School, 2 August minicamps, and weeklong camps during the February and April school vacations.', NULL, NULL, 55, 325, 250, 'week', NULL, NULL, NULL, NULL, 'Summer camps: full refund if you cancel before March 1; from March 1 on, a refund only if the spot is filled from the waiting list. Minicamps: refund only if the spot is filled from the waiting list. Card refunds lose a 5% processing fee. Camp membership fees are not refundable, and there is no refund if a child is removed for behavior. Requests go in writing to parksandrec@hanovernh.org.', NULL, 'Each summer week includes time at Storrs Pond. The Outdoor Adventure minicamp visits Mink Brook every day and includes water activities. The page gives no details on swim instruction, swim tests or lifeguarding.', NULL, NULL, 2026, 'e5f59cb0-fc8e-5021-b63f-c71a48107890', 'hanover-parks-and-recreation-camps-hanover', ST_GeogFromText('SRID=4326;POINT(-72.1852 43.721)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://nh-hanover.civicplus.com/DocumentCenter/View/1277/Camp-Location-Maps','https://www.hanovernh.org/716/Camps','https://www.hanovernh.org/DocumentCenter/View/1145','https://www.hanovernh.org/DocumentCenter/View/8966/Summer-Camp-Themes-2026']::text[], '2026-11-13', '2026-11-13', TRUE),
('Joppa Hill Educational Farm Summer Camp (Farm and Forest Camp)', 'Joppa Hill Educational Farm', 'https://jhef.org/summer-camp/', NULL, NULL, '(603) 472-4724', '174 Joppa Hill Road', 'Bedford', 'NH', '03110', 'New Hampshire', 'day', ARRAY['nature']::text[], NULL, ARRAY['Farm chores and animal care','Gardening','Nature hikes','Woods play / fort building','Crafts','Cooking','Water play','Active games','Orienteering','Hayrides','Campfire','Felting, weaving and dyeing (Animal Arts week)','Engineering design (Animal Engineers week)','Wetland exploration']::text[], NULL, 5, 12, NULL, NULL, 'An all-outdoor farm day camp for ages 5–12 in Bedford, NH. Each week has its own theme, and campers do daily farm chores and animal care, gardening, and time in the woods, 9 AM–3 PM.', NULL, NULL, 375, 375, 375, 'week', TRUE, NULL, FALSE, NULL, 'Cancel more than 6 weeks before the camp week: 95% refund. Cancel 3–6 weeks before: 50% refund. Cancel within 2 weeks: no refund. No refund if a camper is removed for not meeting the independence expectations. Card and ACH processing fees apply.', 'The program is entirely outdoors, with hiking on uneven trails and time outside in all weather. The camp says it "cannot change activities or make significant adjustments for individual campers." Campers must handle basic self-care on their own (port-a-potty, sunscreen, changing clothes). Families who can''t meet these expectations should contact the camp first. The site has an Accessibility page.', 'Afternoon Club Time includes "Water Play," and campers change into water play clothes. The page says nothing about swimming. Wetlands, streams and ponds are explored during Wonderful Wetlands week.', NULL, NULL, 2026, '3faee5c0-fa06-59af-912d-f5c6f2a1b9f6', 'joppa-hill-educational-farm-summer-camp-farm-and-forest-camp-bedford', ST_GeogFromText('SRID=4326;POINT(-71.5369 42.9356)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://jhef.org/summer-camp/']::text[], '2026-11-13', '2026-11-13', TRUE)
